def balanced(text):
    pairs = {")": "(", "]": "[", "}": "{"}
    stack = []
    for ch in text:
        if ch in "([{":
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack

tests = ["(a + b) * [c]", "((()))", "([)]", "{[()]}", "no brackets", "((unclosed"]
for t in tests:
    print(repr(t), "->", balanced(t))

def evaluate(tokens):
    stack = []
    for tok in tokens.split():
        if tok in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if tok == "+": stack.append(a + b)
            elif tok == "-": stack.append(a - b)
            elif tok == "*": stack.append(a * b)
            else: stack.append(a // b)
        else:
            stack.append(int(tok))
    return stack.pop()

print("'3 4 + 5 *' ->", evaluate("3 4 + 5 *"))
print("'10 2 8 * + 3 -' ->", evaluate("10 2 8 * + 3 -"))
print("'7' ->", evaluate("7"))

network = {
