prereqs = {
    "Calculus": ["Algebra"],
    "Algebra": ["Arithmetic"],
    "Statistics": ["Algebra"],
    "Physics": ["Calculus", "Lab Safety"],
    "Lab Safety": ["Physics"],
    "History": [],
}

WHITE, GRAY, BLACK = 0, 1, 2
color = {course: WHITE for course in prereqs}
path = []
cycle = []

def visit(course):
    global cycle
    color[course] = GRAY
    path.append(course)
    for req in prereqs.get(course, []):
        if cycle:
            return
        if color.get(req, BLACK) == GRAY:
            cycle = path[path.index(req):] + [req]
            return
        if color.get(req, BLACK) == WHITE:
            visit(req)
    path.pop()
    color[course] = BLACK

for course in prereqs:
    if color[course] == WHITE and not cycle:
        visit(course)

print("cycle found:", bool(cycle))
print("the loop:", " -> ".join(cycle))

