from collections import deque

steps = {
    "compile": [],
    "test": ["compile"],
    "lint": ["compile"],
    "docs": [],
    "package": ["test", "docs"],
    "deploy": ["package", "lint"],
}

indegree = {step: len(deps) for step, deps in steps.items()}
dependents = {step: [] for step in steps}
for step, deps in steps.items():
    for dep in deps:
        dependents[dep].append(step)

ready = deque(s for s, d in indegree.items() if d == 0)
order = []
while ready:
    step = ready.popleft()
    order.append(step)
    for dependent in dependents[step]:
        indegree[dependent] -= 1
        if indegree[dependent] == 0:
            ready.append(dependent)

print("build order:", order)
print("all steps placed:", len(order) == len(steps))

