class Badge:
    def __init__(self, code):
        self.code = code
    def __hash__(self):
        return hash(self.code)
    def __eq__(self, other):
        return isinstance(other, Badge) and self.code == other.code
    def __repr__(self):
        return f"Badge({self.code})"

