vocabulary = ["apple", "application", "apply", "apt", "banana",
              "band", "banner", "canal", "canopy", "dog"]

trie = {}
for word in vocabulary:
    node = trie
    for ch in word:
        node = node.setdefault(ch, {})
    node["$"] = word

def completions(prefix):
    node = trie
    for ch in prefix:
        if ch not in node:
            return []
        node = node[ch]
    found = []
    def walk(subtree):
        for key, value in subtree.items():
            if key == "$":
                found.append(value)
            else:
                walk(value)
    walk(node)
    return sorted(found)

print("prefix 'app':", completions("app"))
print("prefix 'ban':", completions("ban"))
print("prefix 'can':", completions("can"))
print("prefix 'z':", completions("z"))

